//! 🧪️ Original boxed camera leaves remain projected while native semantic previews preserve every physical receipt.
use super::*;
use crate::camera_owner::{IdentityWindowOwner,RetainedLoadCameraConfig,RetainedLoadCameraConfigMutation};
use semio_framework_value::{retained_clone::original_slot::RetainedOriginalSlot,retirement::controlled::ControlledRetirement};
fn granted(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn close_typed<T:semio_framework_value::retirement::RetireOwned>(original:T){let mut owner=ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();for _ in 0..65536{if owner.terminal_is_empty(){return;}let d=owner.next_demand(4096).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(granted(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("native preview original typed owner did not close");}
#[semio_framework_async_macros::async_test]
async fn original_window_semantic_preview_matches_portable_outputs_and_retains_boxed_press_sources(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();
 for law in corpus["cases"].as_array().unwrap(){let mut typed=TypedWindowConfigStoreOwner::<IdentityWindowOwner>{direct_ingress:ControlledRetirement::new(DirectIngress{mutations:Vec::new(),allocations:Vec::new(),addresses:Vec::new()}).map_err(|(e,_)|e).unwrap(),partitions:WindowRegistry::new(),partition_close_cursor:0,partition_address_retirement:None,actor:Some(protocol::ActorId("original-preview-actor".into())),actor_retirement:None};
  let partition=typed.partition("original-preview-window").await.unwrap();for _ in 0..65536{if partition.store.owned_disposer_installed(){break;}let d=partition.catalog_demands(4096).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||partition.catalog_step(granted(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(partition.store.owned_disposer_installed());let g=granted(WindowSemanticPreview::<IdentityWindowOwner>::birth_demand());let(admitted,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||WindowSemanticPreview::begin(&partition.store,g).unwrap().unwrap());let(mut preview,p)=admitted;assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));let mut allow=|_|true;let mut receiving=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new_retained(&mut allow);
  for leaf in law["leaves"].as_array().unwrap(){let mut config=RetainedLoadCameraConfig::default();config.eye=std::array::from_fn(|i|leaf[i].as_f64().unwrap());let mutation=WindowConfigMutation::of::<IdentityWindowOwner>("original-preview-window",RetainedLoadCameraConfigMutation::Snapshot{config:Box::new(config)});let payload=mutation.mutation.as_any().downcast_ref::<RetainedLoadCameraConfigMutation>().unwrap()as*const _;let mut slot=RetainedOriginalSlot::new(mutation);let key=slot.key();let factory:Arc<dyn store::ArtifactOwnedValueRetirementFactory<WindowConfigMutation>>=Arc::new(semio_framework_value::OwnedValueRetirementFactory::<WindowConfigMutation>::default());for _ in 0..2{let d=slot.demands(key).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||slot.advance_read(key,&factory,granted(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
   let pg=granted(semio_framework_value::retained_clone::RetainedOwnedProjection::<WindowConfigMutation>::constructor_demand());let(retained,_)=semio_framework_trace::observe_heap_allocations_on_this_thread(||slot.retain_read(key,pg).unwrap());let(mut projection,_)=retained;let g=granted(WindowSemanticPreview::<IdentityWindowOwner>::input_demand());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||preview.admit_input(&projection,g).unwrap().unwrap());for _ in 0..65536{if projection.terminal_is_empty(){break;}let d=projection.close_demand(4096).unwrap();projection.close_step(granted(d)).unwrap();}assert!(projection.terminal_is_empty());assert_eq!((heap.requested_bytes,heap.released_bytes),(result.retained_capacity_bytes,result.released_bytes));assert_eq!(slot.get().mutation.as_any().downcast_ref::<RetainedLoadCameraConfigMutation>().unwrap()as*const _,payload);
   for _ in 0..65536{if preview.leaf_ready(){break;}let d=preview.demand(&partition.store,4096).unwrap();let g=granted(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||preview.step(&partition.store,denied,Some(&mut receiving)).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||preview.step(&partition.store,g,Some(&mut receiving)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(preview.leaf_ready());close_typed(slot);let mut authority=semio_framework_value::FactoryAuthority::new(factory);while !authority.terminal_is_empty(){authority.step(granted(authority.demands(4096).unwrap())).unwrap();}
  }
  let demand=RetirementDemand{copy_bytes:size_of::<ArtifactDerivedSnapshot<RetainedLoadCameraConfig>>(),depth:1,..Default::default()};let(output,_):(ArtifactDerivedSnapshot<RetainedLoadCameraConfig>,_)=preview.take_base(granted(demand)).unwrap().unwrap();assert_eq!(serde_json::to_value(output.snapshot().eye).unwrap(),law["expected"]);let mut original=Some(output);let g=granted(RetirementDemand{capacity_bytes:store::ArtifactStore::<RetainedLoadCameraConfig,RetainedLoadCameraConfigMutation>::history_read_retirement_birth_bytes(),depth:1,..Default::default()});let(retire,_)=admit_original_snapshot_alias(&mut original,partition.store.owned_snapshot_retirement_factory().unwrap(),partition.store.owned_mutation_retirement_factory().unwrap(),g).unwrap().unwrap();let mut active=Some(retire);for _ in 0..65536{if active.is_none(){break;}let d=semio_framework_value::factory_ticket_demands(active.as_ref().unwrap(),4096).unwrap();let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_value::close_factory_ticket(&mut active,granted(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(active.is_none());
  preview.cancel();for _ in 0..65536{if preview.terminal_is_empty(){break;}let d=preview.demand(&partition.store,4096).unwrap();preview.step(&partition.store,granted(d),None).unwrap();}assert!(preview.terminal_is_empty());for _ in 0..65536{if typed.terminal_is_empty(){break;}let d=typed.retirement_demands(4096).unwrap();typed.close_step(granted(d)).unwrap();}assert!(typed.terminal_is_empty());
 }
}
